@Mod.EventBusSubscriber(modid="thaumcraft")
public final class AccessoryProbe {
 public static final BlockPos P=new BlockPos(3360,205,8);static int stage,ticks;static long due;static ServerPlayer actor;public static volatile boolean ready;
 static String mode(){return System.getProperty("thaumcraft.alchemyProbe","");}
 static void check(boolean b,String text){if(!b)throw new AssertionError(text);}
 static ItemStack item(String n){return new ItemStack(net.minecraft.core.registries.BuiltInRegistries.ITEM.getValue(SimpleContent.id(n)));}
 static void fill(ServerPlayer p){var s=AccessorySlots.storage(p);for(int i=0;i<7;i++)s.setItem(i,ItemStack.EMPTY);for(var e:Map.of(0,"amulet_vis",1,"ring_cloud",2,"ring_cloud",4,"band_curiosity",6,"charm_verdant_life").entrySet()){var stack=item(e.getValue());stack.set(EquipmentContent.RUNIC.get(),e.getKey()==1?2:e.getKey()==2?3:1);s.setItem(e.getKey(),stack);}s.getItem(6).set(thaumcraft.devices.DeviceContent.CHARGE.get(),100);AccessorySlots.flush(p);}
 static void basics(ServerLevel l){actor.setPos(Vec3.atBottomCenterOf(P));actor.getInventory().clearContent();var s=AccessorySlots.storage(actor);check(s!=null&&s.getContainerSize()==7,"missing seven slots");check(!AccessorySlots.accepts(1,item("band_curiosity"))&&AccessorySlots.accepts(4,item("band_curiosity"))&&!AccessorySlots.accepts(3,item("ring_cloud")),"slot types incorrect");actor.setItemInHand(InteractionHand.MAIN_HAND,item("ring_cloud"));check(AccessorySlots.equip(actor,actor.getMainHandItem())&&actor.getMainHandItem().isEmpty()&&s.getItem(1).getCount()==1,"first ring equip duplicated");actor.setItemInHand(InteractionHand.MAIN_HAND,item("ring_cloud"));check(AccessorySlots.equip(actor,actor.getMainHandItem())&&s.getItem(2).getCount()==1,"second ring not equipped");actor.setItemInHand(InteractionHand.MAIN_HAND,item("ring_cloud"));check(AccessorySlots.equip(actor,actor.getMainHandItem())&&actor.getMainHandItem().getCount()==1,"swap lost previous ring");actor.getInventory().clearContent();fill(actor);s=AccessorySlots.storage(actor);check(EquipmentContent.maxShield(actor)==8,"runic shield did not sum physical slots");actor.setItemInHand(InteractionHand.OFF_HAND,item("charm_voidseer"));thaumcraft.persistence.PlayerWarpStore.write(actor,new thaumcraft.persistence.PlayerWarpStore.State(1,100,0,0,0));check(EquipmentContent.visCost(actor,100)==75&&thaumcraft.warp.WarpEngine.gear(actor)==5,"legacy offhand or voidseer warp lost");actor.setItemInHand(InteractionHand.OFF_HAND,ItemStack.EMPTY);
  actor.setHealth(18);actor.tickCount=40;thaumcraft.aura.AuraData.get(l).put(thaumcraft.aura.AuraCell.key(P.getX()>>4,P.getZ()>>4),new thaumcraft.aura.AuraCell(500,500,0));EquipmentContent.tickPlayer(actor);check(actor.getHealth()==19&&RechargeHelper.getCharge(s.getItem(6))==99,"worn verdant did not recharge/heal with exact charge");actor.setOnGround(false);check(CloudJump.jump(actor)&&actor.getDeltaMovement().y==.75&&!CloudJump.jump(actor),"slotted cloud ring impulse/replay incorrect");
  var good=actor.getPersistentData().get(AccessorySlots.ID).copy();var future=new net.minecraft.nbt.CompoundTag();future.putInt("version",2);actor.getPersistentData().put(AccessorySlots.ID,future);check(AccessorySlots.storage(actor)==null&&!AccessorySlots.equip(actor,item("ring_cloud"))&&actor.getPersistentData().get(AccessorySlots.ID).equals(future),"future accessory state overwritten");actor.getPersistentData().put(AccessorySlots.ID,good);s=AccessorySlots.storage(actor);check(RechargeHelper.getCharge(s.getItem(6))==99,"charge was not persisted");
  var menu=new AccessoryMenu(12,actor.getInventory(),s);s.setItem(6,ItemStack.EMPTY);actor.getInventory().setItem(9,item("charm_undying"));check(!menu.quickMoveStack(actor,7).isEmpty()&&actor.getInventory().getItem(9).isEmpty()&&s.getItem(6).getCount()==1&&menu.quickMoveStack(actor,7).isEmpty(),"quick move duplicated or used wrong slot");check(AccessorySlots.protect(actor,actor.damageSources().generic())&&s.getItem(6).isEmpty()&&actor.getHealth()==1&&actor.hasEffect(MobEffects.REGENERATION)&&actor.hasEffect(MobEffects.ABSORPTION)&&!actor.hasEffect(MobEffects.FIRE_RESISTANCE)&&!AccessorySlots.protect(actor,actor.damageSources().generic()),"undying charm duplicated or wrong original effects");actor.removeAllEffects();
  fill(actor);boolean keep=l.getGameRules().get(net.minecraft.world.level.gamerules.GameRules.KEEP_INVENTORY);l.getGameRules().set(net.minecraft.world.level.gamerules.GameRules.KEEP_INVENTORY,false,l.getServer());var drops=new ArrayList<net.minecraft.world.entity.item.ItemEntity>();net.minecraftforge.event.entity.living.LivingDropsEvent.BUS.post(new net.minecraftforge.event.entity.living.LivingDropsEvent(actor,actor.damageSources().generic(),drops,false));check(drops.size()==5&&AccessorySlots.equipped(actor).isEmpty(),"death did not remove/drop each physical item once");net.minecraftforge.event.entity.living.LivingDropsEvent.BUS.post(new net.minecraftforge.event.entity.living.LivingDropsEvent(actor,actor.damageSources().generic(),drops,false));check(drops.size()==5,"death replay duplicated items");fill(actor);l.getGameRules().set(net.minecraft.world.level.gamerules.GameRules.KEEP_INVENTORY,true,l.getServer());net.minecraftforge.event.entity.living.LivingDropsEvent.BUS.post(new net.minecraftforge.event.entity.living.LivingDropsEvent(actor,actor.damageSources().generic(),drops,false));check(drops.size()==5&&AccessorySlots.equipped(actor).size()==5,"keep inventory lost accessories");l.getGameRules().set(net.minecraft.world.level.gamerules.GameRules.KEEP_INVENTORY,keep,l.getServer());
  var next=PrimordialProbe.fake(l);net.minecraftforge.event.entity.player.PlayerEvent.Clone.BUS.post(new net.minecraftforge.event.entity.player.PlayerEvent.Clone(next,actor,true));check(EquipmentContent.maxShield(next)==8&&RechargeHelper.getCharge(AccessorySlots.storage(next).getItem(6))==100,"clone lost slot components");
  l.setBlockAndUpdate(P.east(12),Blocks.CHEST.defaultBlockState());var chest=(ChestBlockEntity)l.getBlockEntity(P.east(12));AccessorySlots.flush(actor);var savedTag=new net.minecraft.nbt.CompoundTag();savedTag.put("accessories_probe",actor.getPersistentData().get(AccessorySlots.ID).copy());var savedItem=new ItemStack(Items.STICK);savedItem.set(net.minecraft.core.component.DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(savedTag));chest.setItem(26,savedItem);chest.setChanged();
  Thaumcraft.LOGGER.info("ACCESSORIES_NATIVE_OK: typed slots, two rings, safe swaps and quick move, exact runic/voidseer effects, worn recharge/heal, cloud jump replay guard, future data preservation, original undying, death/keep inventory/clone conservation");
 }
 static void masks(ServerLevel l){var helm=item("fortress_helm");helm.setDamageValue(73);helm.set(EquipmentContent.RUNIC.get(),3);helm.set(net.minecraft.core.component.DataComponents.CUSTOM_NAME,net.minecraft.network.chat.Component.literal("Keep me"));for(String key:List.of("mask_0","mask_1","mask_2","fortress_goggles")){var recipe=l.recipeAccess().getRecipes().stream().map(h->h.value()).filter(r->r instanceof InfusionRecipe f&&f.enchantment().equals(key)).map(r->(InfusionRecipe)r).findFirst().orElseThrow();var offerings=new ArrayList<ItemStack>();for(var component:recipe.components())offerings.add(new ItemStack(component.item().items().findFirst().orElseThrow()));var input=new InfusionInput(helm,offerings);check(recipe.assignment(input)!=null&&recipe.aspects(input).equals(recipe.aspects()),"mask recipe rejected correct ingredients/cost");var result=recipe.assemble(input);check(result.getDamageValue()==73&&EquipmentContent.runic(result)==3&&result.getHoverName().getString().equals("Keep me"),"mask infusion erased actual helmet components");check(!FortressMasks.accepts(result,key),"same upgrade reapplied");helm=result;}
  actor.setItemSlot(EquipmentSlot.HEAD,helm);check(FortressMasks.worn(actor)==2&&FortressMasks.hasGoggles(actor)&&EquipmentContent.visCost(actor,100)==95,"mask/goggles not equipped together");var victim=EntityTypes.COW.create(l,EntitySpawnReason.TRIGGERED);victim.setNoAi(true);victim.setPos(Vec3.atBottomCenterOf(P));l.addFreshEntity(victim);actor.setHealth(10);net.minecraftforge.event.entity.living.LivingHurtEvent.BUS.post(new net.minecraftforge.event.entity.living.LivingHurtEvent(victim,actor.damageSources().playerAttack(actor),12));check(actor.getHealth()==11,"sipping fiend not healing");actor.setItemSlot(EquipmentSlot.HEAD,FortressMasks.apply(helm,"mask_1"));net.minecraftforge.event.entity.living.LivingHurtEvent.BUS.post(new net.minecraftforge.event.entity.living.LivingHurtEvent(actor,actor.damageSources().mobAttack(victim),10));check(victim.hasEffect(MobEffects.WITHER),"angry ghost not retaliating");actor.setItemSlot(EquipmentSlot.HEAD,ItemStack.EMPTY);victim.discard();((ChestBlockEntity)l.getBlockEntity(P.east(12))).setItem(0,helm);Thaumcraft.LOGGER.info("MASKS_NATIVE_OK: all four original infusions, damage/name/runic preservation, mask replacement, duplicate rejection, goggles discount, life steal and wither retaliation");}
 static void read(ServerLevel l){var chest=(ChestBlockEntity)l.getBlockEntity(P.east(12));actor.getPersistentData().put(AccessorySlots.ID,chest.getItem(26).get(net.minecraft.core.component.DataComponents.CUSTOM_DATA).copyTag().get("accessories_probe").copy());check(EquipmentContent.maxShield(actor)==8&&RechargeHelper.getCharge(AccessorySlots.storage(actor).getItem(6))==100,"native restart lost slots/charge");actor.setItemSlot(EquipmentSlot.HEAD,chest.getItem(0));check(FortressMasks.worn(actor)==2&&FortressMasks.hasGoggles(actor)&&EquipmentContent.runic(chest.getItem(0))==3&&chest.getItem(0).getDamageValue()==73,"native restart lost helmet upgrades");actor.setItemSlot(EquipmentSlot.CHEST,item("fortress_chest"));actor.setItemSlot(EquipmentSlot.LEGS,item("fortress_legs"));EquipmentContent.updateFortress(actor);check(actor.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.ARMOR).getModifier(net.minecraft.resources.Identifier.parse("thaumcraft:fortress_set")).amount()==6&&actor.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.ARMOR_TOUGHNESS).getModifier(net.minecraft.resources.Identifier.parse("thaumcraft:fortress_set")).amount()==3,"fortress set/mask bonuses incorrect");for(var slot:List.of(EquipmentSlot.HEAD,EquipmentSlot.CHEST,EquipmentSlot.LEGS))actor.setItemSlot(slot,ItemStack.EMPTY);EquipmentContent.updateFortress(actor);check(actor.getAttributeValue(net.minecraft.world.entity.ai.attributes.Attributes.ARMOR)==0,"unequipping retained set bonus");var slots=AccessorySlots.storage(actor);slots.setItem(1,item("ring_apprentice"));slots.setItem(2,item("ring_apprentice"));check(EquipmentContent.visCost(actor,100)==90&&AccessorySlots.accepts(3,item("girdle_mundane")),"basic jewelry slots or apprentice discounts failed");Thaumcraft.LOGGER.info("ACCESSORIES_RESTART_OK: seven slots, charge/runic components and masked/goggled named damaged helmet survived native world restart");stage=9;l.getServer().halt(false);}
 static void gallery(ServerLevel l){l.getServer().setDifficulty(net.minecraft.world.Difficulty.NORMAL,true);actor.removeAllEffects();actor.setGameMode(net.minecraft.world.level.GameType.CREATIVE);actor.teleportTo(l,P.getX()+.5,P.getY()+2,P.getZ()+8.5,Set.of(),180,8,true);actor.getAbilities().flying=true;actor.onUpdateAbilities();actor.getInventory().clearContent();fill(actor);var helm=FortressMasks.apply(item("fortress_helm"),"mask_0");helm=FortressMasks.apply(helm,"fortress_goggles");actor.setItemSlot(EquipmentSlot.HEAD,helm);actor.setItemSlot(EquipmentSlot.CHEST,item("fortress_chest"));actor.setItemSlot(EquipmentSlot.LEGS,item("fortress_legs"));for(int i=0;i<3;i++){var stand=EntityTypes.ARMOR_STAND.create(l,EntitySpawnReason.TRIGGERED);stand.setPos(Vec3.atBottomCenterOf(P.offset((i-1)*4,0,0)));String family=new String[]{"crimson_plate_","crimson_robe_","crimson_praetor_"}[i];for(var pair:Map.of("helm",EquipmentSlot.HEAD,"chest",EquipmentSlot.CHEST,"legs",EquipmentSlot.LEGS).entrySet())stand.setItemSlot(pair.getValue(),item(family+pair.getKey()));stand.setItemSlot(EquipmentSlot.FEET,item("crimson_boots"));stand.setItemSlot(EquipmentSlot.MAINHAND,item("crimson_blade"));l.addFreshEntity(stand);}ready=true;stage=9;Thaumcraft.LOGGER.info("ACCESSORIES_CLIENT_OK: seven equipped physical slots and three original cult armor sets; B opens native accessories menu");}
 @SubscribeEvent public static void tick(TickEvent.ServerTickEvent.Post e){if(!mode().startsWith("accessory-"))return;var l=e.server().overworld();if(++ticks<80||stage==9)return;if(stage==0){if(e.server().isDedicatedServer())actor=PrimordialProbe.fake(l);else{if(e.server().getPlayerList().getPlayers().isEmpty())return;actor=e.server().getPlayerList().getPlayers().getFirst();}for(int x=209;x<=212;x++)for(int z=-1;z<=1;z++)l.setChunkForced(x,z,true);due=l.getGameTime()+50;stage=1;return;}if(stage==1&&l.getGameTime()>=due){if(mode().equals("accessory-read")){read(l);return;}l.getEntitiesOfClass(Entity.class,new AABB(P).inflate(30),x->!(x instanceof net.minecraft.world.entity.player.Player)).forEach(Entity::discard);for(var p:BlockPos.betweenClosed(P.offset(-10,-1,-8),P.offset(14,6,10)))l.setBlockAndUpdate(p,p.getY()==P.getY()-1?Blocks.GLOWSTONE.defaultBlockState():Blocks.AIR.defaultBlockState());if(mode().equals("accessory-client")){gallery(l);return;}basics(l);masks(l);stage=9;e.server().halt(false);}}
}
